SEVERANCE_ALLOWANCE.eligibility:
const start = get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from);
const months = calendar_completed_months(start, ctx.entry.incurred_on);
if (!(ctx.entry.quantity > 0)) return false;
if (!(ctx.entry.incurred_on >= start)) return false;
const end = get(ctx.subject.employment.effective_range, 'to', null);
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
if (!(months >= ctx.lookup.qualifying_service_months)) return false;
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
if (get(facts, 'pension_eligible', false) === true) return false;
if (get(facts, 'absent_five_days', false) === true) return false;
if (get(facts, 'unlawful_resignation', false) === true) return false;
return true;

SEVERANCE_ALLOWANCE.conversion:
// quantity: the months HR counted under art.46(2), service less unemployment-insured time and time already paid.
// Decree 145/2020/NĐ-CP art.8(5): the average contractual monthly wage of the six months before the contract ends, recorded on the exit review.
const wage = Number(get(ctx.subject.employment, 'employee_extension_data.encashment_review.average_contract_wage_vnd', 0));
if (!(wage > 0))
	throw 'Record the six-month average contractual wage on the exit review (encashment_review.average_contract_wage_vnd).';
const full_years = Math.trunc(ctx.entry.quantity / 12);
const remainder = ctx.entry.quantity % 12;
const half_month = wage * ctx.lookup.half_month_share;
if (remainder > ctx.lookup.half_year_remainder_months) return half_month * (full_years + 1);
if (remainder > 0) return half_month * (full_years + ctx.lookup.half_year_share);
return half_month * full_years;

JOB_LOSS_ALLOWANCE.eligibility:
const start = get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from);
const months = calendar_completed_months(start, ctx.entry.incurred_on);
if (!(ctx.entry.incurred_on >= start)) return false;
const end = get(ctx.subject.employment.effective_range, 'to', null);
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
if (!(months >= ctx.lookup.qualifying_service_months)) return false;
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
return get(facts, 'unlawful_resignation', false) !== true;

JOB_LOSS_ALLOWANCE.conversion:
// quantity: the months HR counted under art.47(2); zero still pays the two-month minimum (Decree 145/2020 art.8(2)).
// Decree 145/2020/NĐ-CP art.8(5): the average contractual monthly wage of the six months before the contract ends, recorded on the exit review.
const wage = Number(get(ctx.subject.employment, 'employee_extension_data.encashment_review.average_contract_wage_vnd', 0));
if (!(wage > 0))
	throw 'Record the six-month average contractual wage on the exit review (encashment_review.average_contract_wage_vnd).';
const full_years = Math.trunc(ctx.entry.quantity / 12);
const remainder = ctx.entry.quantity % 12;
const pay = (years) => wage * Math.max(years, ctx.lookup.minimum_months);
if (remainder > ctx.lookup.half_year_remainder_months) return pay(full_years + 1);
if (remainder > 0) return pay(full_years + ctx.lookup.half_year_share);
return pay(full_years);

