INSURANCE_EQUIVALENT.conversion:
const employment = ctx.subject.employment;
const terms = employment.terms;
const extension = get(employment, 'employee_extension_data', {});
const review = get(extension, 'insurance_review', null);
const current =
	get(review, 'month', '') === String(ctx.as_of).substring(0, 7) ? review : null;
const monthly = Number(get(terms, 'rate.amount', 0));
const fixed = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const wage = Number(get(current, 'salary_vnd', monthly + fixed));
const signed = get(employment, 'signed_contract_period', null);
const months =
	signed?.from == null || signed.to == null
		? Infinity
		: calendar_completed_months(signed.from, add_days(signed.to, 1));
const probation = get(terms, 'probation_period', null);
// Law 41/2024/QH15 art.2(1)(a): only a separate probation contract is outside the schemes.
const onProbation =
	probation != null &&
	String(ctx.run.salary_coverage.from) <= probation.to &&
	get(extension, 'separate_probation_contract', false) === true;
const foreign = !ctx.lookup.vietnamese_nationality.includes(String(get(employment, 'payroll.nationality', 'VN')));
const excluded =
	get(extension, 'receiving_pension', false) === true ||
	get(extension, 'domestic_worker', false) === true ||
	get(extension, 'pass_type', '') === 'INTRA_COMPANY_TRANSFER' ||
	months < 1 ||
	(foreign && months < 12) ||
	(employment.engagement === 'PART_TIME' && wage < ctx.lookup.insurance_floor) ||
	onProbation;
const insured = Math.min(
	Math.max(wage, ctx.lookup.insurance_floor),
	ctx.lookup.insurance_ceiling
);
const region = String(get(ctx.subject.employer.entity_extension_data, 'region', 'I'));
const minimum = get(ctx.lookup.minimum_wage.by_region, region, ctx.lookup.minimum_wage.by_region.I);
const unemployment = Math.min(
	Math.max(wage, ctx.lookup.insurance_floor),
	minimum * ctx.lookup.ui_cap_multiple
);
const si =
	excluded ||
	get(extension, 'statutory.SI.si_treaty_exempt', false) === true ||
	get(current, 'si_temporarily_suspended', false) === true;
const hi = excluded || get(extension, 'statutory.HI.hi_treaty_exempt', false) === true;
const ui =
	excluded ||
	foreign ||
	get(extension, 'statutory.UI.pension_qualified', false) === true;
return (
	(si ? insured * ctx.lookup.si_employer_rate : 0) +
	(hi ? insured * ctx.lookup.hi_employer_rate : 0) +
	(ui ? unemployment * ctx.lookup.ui_employer_rate : 0)
);

