PIT_TAXABLE_INCOME.employer_amount:
// The month's taxable income, less what this month already counted: each subtotal holds one treatment, so every cap applies to what the month paid.
const month = get(ctx.balances, 'month', {});
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const extension = get(ctx.subject.employment, 'employee_extension_data', {});
const subtotal = (code) => Number(get(ctx.subtotals, code, 0));
const meal = subtotal('MEAL_PAY') - subtotal('PAID_BASIC');
const workExpense = subtotal('WORK_EXPENSE_PAY') - subtotal('MEAL_PAY');
// Housing the employer pays is no pay line: the contract amount, on the share of the salary BASIC pays, on-cycle.
const housingRate = Number(get(ctx.subject.employment, 'terms.rate.amount', 0));
const housingAmount = Number(get(ctx.subject.employment, 'terms.allowances.HOUSING.amount', 0));
const housing =
	get(ctx.run, 'kind', '') === 'OFF_CYCLE' || get(ctx.subject.employment, 'terms.rate.unit', '') !== 'MONTHLY'
		? 0
		: round(housingRate > 0 ? (housingAmount * subtotal('BASIC')) / housingRate : housingAmount);
const outside = subtotal('PIT_EXEMPT_PAY') - subtotal('PENSION_PAY');
// Statutory pay above what an employer's own rest-day multiple adds; that excess stays taxable.
const workDays = get(ctx, 'work.days', []);
const holidayDay = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const restDay = (d) => get(d, 'day_type', '') === 'REST' && !holidayDay(d);
const employerRest = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const aboveStatute =
	employerRest > ctx.lookup.rest_day_multiple
		? sum(workDays.filter(restDay).map((d) => Number(get(d, 'worked_hours', 0)) * Number(get(d, 'hour_rate', 0)))) *
			(employerRest - ctx.lookup.rest_day_multiple)
		: 0;
const statutoryOvertime = Math.max(0, Number(ctx.overtime) - aboveStatute);
// The normal-hour part of that pay: the clocked overtime hours of a working or off day and every hour of a rest day or holiday.
const ordinaryOvertime = sum(
	workDays.map(
		(d) =>
			Number(get(d, 'hour_rate', 0)) *
			(holidayDay(d) || get(d, 'day_type', '') === 'REST'
				? Number(get(d, 'worked_hours', 0))
				: ['WORK', 'OFF'].includes(get(d, 'day_type', ''))
					? Number(get(d, 'overtime_hours', 0))
					: 0)
	)
);
// Circular 111/2013/TT-BTC art.3(1)(i): only the part of night and overtime pay above the normal-hour pay is exempt.
const exemptOvertime = Math.max(0, statutoryOvertime - ordinaryOvertime);
const fixedMealCap = ctx.lookup.meal_allowance_cap;
const mealCap =
	fixedMealCap == null
		? get(extension, 'cash_meal_policy_limit_vnd', null)
		: fixedMealCap;
if (mealCap == null && meal > 0)
	throw 'Record the documented cash-meal policy limit for this pay month.';
const employerLimit = Number(
	get(ctx.subject.employer.entity_extension_data, 'work_expense_limit', 0)
);
const wages = Math.max(
	0,
	subtotal('ADDITIONAL_WAGES') - meal - workExpense - outside - exemptOvertime
);
const ratio = ctx.lookup.housing_exempt_ratio;
const counted = before('PIT_TAXABLE_INCOME.employer');
const earlierMeal = before('MEAL_PAY') - before('PAID_BASIC');
const earlierWorkExpense = before('WORK_EXPENSE_PAY') - before('MEAL_PAY');
const rate = Number(get(ctx.subject.employment, 'terms.rate.amount', 0));
const earlierHousing = rate > 0 ? (Number(get(ctx.subject.employment, 'terms.allowances.HOUSING.amount', 0)) * before('BASIC')) / rate : 0;
const capped = (paidMeal, paidExpense) =>
	Math.max(0, paidMeal - Number(mealCap ?? 0)) + Math.max(0, paidExpense - employerLimit);
const otherTaxable =
	Math.max(counted - earlierHousing, counted / (1 + ratio)) +
	wages +
	capped(earlierMeal + meal, earlierWorkExpense + workExpense) -
	capped(earlierMeal, earlierWorkExpense);
return Math.max(0, otherTaxable + Math.min(earlierHousing + housing, ratio * otherTaxable) - counted);

PIT_PENSION_DEDUCTION.employer_amount:
// Art.46(2)(a): the employer's contribution and the worker's own share one monthly cap. An off-cycle run adds no second month of the worker's own.
const subtotal = (code) => Number(get(ctx.subtotals, code, 0));
const own = get(ctx.run, 'kind', 'ON_CYCLE') === 'OFF_CYCLE'
	? 0
	: Number(get(get(ctx.subject.employment, 'employee_extension_data.statutory.PIT', {}), 'voluntary_pension_contribution', 0));
return Math.min(subtotal('PENSION_PAY') - subtotal('HOUSING_PAY') + own, ctx.lookup.pension_cap);

PIT.employee_amount:
const employment = ctx.subject.employment;
const terms = employment.terms;
const pit = get(employment, 'employee_extension_data.statutory.PIT', {});
// A recovery takes back income the memo row cannot hold below zero.
const remuneration = Number(get(ctx.statutory, 'PIT_TAXABLE_INCOME.employer', 0)) + Math.min(0, Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0)));
const residency = get(terms, 'residency_status', null);
if (residency == null)
	throw 'Record the tax residence on the sealed contract (CITIZEN, PERMANENT_RESIDENT, RESIDENT or NON_RESIDENT); Vietnamese law presumes neither residence nor non-residence.';
const signed = get(employment, 'signed_contract_period', null);
const shortContract =
	get(signed, 'to', null) != null &&
	add_months(signed.from, ctx.lookup.short_term_months) > add_days(signed.to, 1);
const shortTerm =
	shortContract || ['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(get(employment, 'engagement', ''));
const committed = get(pit, 'commitment_form', false) === true;
const borne = get(terms, 'employer_bears_income_tax', false) === true;
// Circular 111/2013/TT-BTC art.7 and Annex 02: only the tax the employer bears is income; the allowances the contract leaves to the employee bear their own share at the month's rate.
const items = !borne || get(ctx.run, 'kind', '') === 'OFF_CYCLE' ? 0 : sum(get(terms, 'employee_borne_tax_items', []).map((code) => Number(get(terms, 'allowances.' + code + '.amount', 0))));
if (borne && items === 0) return 0;
const taxed = borne ? Math.max(0, Math.min(items, remuneration)) : remuneration;
if (residency === 'NON_RESIDENT') return taxed * ctx.lookup.non_resident_rate;
if (shortTerm && committed) return 0;
if (shortTerm && remuneration < ctx.lookup.short_term_threshold) return 0;
if (shortTerm) return taxed * ctx.lookup.short_term_rate;
const insurance =
	Number(get(ctx.statutory, 'SI.employee', 0)) +
	Number(get(ctx.statutory, 'HI.employee', 0)) +
	Number(get(ctx.statutory, 'UI.employee', 0));
const pension = Number(get(ctx.statutory, 'PIT_PENSION_DEDUCTION.employer', 0));
const dependants = Number(get(pit, 'dependants', 0));
const month = get(ctx.balances, 'month', {});
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const before = (code, side) => heldIn(paidMonth, code + '.' + side);
const earlierInsurance = before('SI', 'employee') + before('HI', 'employee') + before('UI', 'employee');
const monthlyDeduction = ctx.lookup.personal_deduction + ctx.lookup.dependant_deduction * dependants;
const assessable = Math.max(
	0,
	before('PIT_TAXABLE_INCOME', 'employer') +
		remuneration -
		earlierInsurance -
		insurance -
		Math.min(before('PIT_PENSION_DEDUCTION', 'employer') + pension, ctx.lookup.pension_cap) -
		monthlyDeduction
);
const income = before('PIT_TAXABLE_INCOME', 'employer') + Number(get(ctx.statutory, 'PIT_TAXABLE_INCOME.employer', 0));
const split = (base) => {
	let employer = 0;
	let employee = 0;
	for (let index = 0; index < 20; index += 1) {
		const tax = ladder(Math.max(0, base + employer), ctx.lookup.brackets);
		employee = items > 0 && income > 0 ? (tax * Math.min(items, income)) / (income + employer) : 0;
		employer = tax - employee;
	}
	return { employer, employee };
};
if (borne) return split(assessable).employee - before('PIT', 'employee');
// The month's taxable income through the monthly column; the annual column is the finalisation's.
// An excess is recorded on the payslip and credited in the annual finalisation.
return ladder(assessable, ctx.lookup.brackets) - before('PIT', 'employee');

PIT.employer_amount:
const employment = ctx.subject.employment;
const terms = employment.terms;
const pit = get(employment, 'employee_extension_data.statutory.PIT', {});
const remuneration = Number(get(ctx.statutory, 'PIT_TAXABLE_INCOME.employer', 0));
const residency = get(terms, 'residency_status', null);
if (residency == null)
	throw 'Record the tax residence on the sealed contract (CITIZEN, PERMANENT_RESIDENT, RESIDENT or NON_RESIDENT); Vietnamese law presumes neither residence nor non-residence.';
const signed = get(employment, 'signed_contract_period', null);
const shortContract =
