const committed = get(pit, 'commitment_form', false) === true;
if (get(terms, 'employer_bears_income_tax', false) !== true) return 0;
// Circular 111/2013/TT-BTC art.7 and Annex 02: only the tax the employer bears is income; the allowances the contract leaves to the employee bear their own share at the month's rate.
