const own = Math.max(0, Math.min(items, remuneration));
if (residency === 'NON_RESIDENT')
	return ((remuneration - own) * ctx.lookup.non_resident_rate) / (1 - ctx.lookup.non_resident_rate);
if (shortTerm && committed) return 0;
if (shortTerm && remuneration < ctx.lookup.short_term_threshold) return 0;
if (shortTerm) return ((remuneration - own) * ctx.lookup.short_term_rate) / (1 - ctx.lookup.short_term_rate);
const insurance =
	Number(get(ctx.statutory, 'SI.employee', 0)) +
	Number(get(ctx.statutory, 'HI.employee', 0)) +
	Number(get(ctx.statutory, 'UI.employee', 0));
const pension = Number(get(ctx.statutory, 'PIT_PENSION_DEDUCTION.employer', 0));
const dependants = Number(get(pit, 'dependants', 0));
const month = get(ctx.balances, 'month', {});
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const before = (code, side) => heldIn(paidMonth, code + '.' + side);
const earlierInsurance = before('SI', 'employee') + before('HI', 'employee') + before('UI', 'employee');
const monthlyDeduction = ctx.lookup.personal_deduction + ctx.lookup.dependant_deduction * dependants;
const assessable = Math.max(
	0,
	before('PIT_TAXABLE_INCOME', 'employer') +
		remuneration -
		earlierInsurance -
		insurance -
		Math.min(before('PIT_PENSION_DEDUCTION', 'employer') + pension, ctx.lookup.pension_cap) -
		monthlyDeduction
);
const income = before('PIT_TAXABLE_INCOME', 'employer') + Number(get(ctx.statutory, 'PIT_TAXABLE_INCOME.employer', 0));
const split = (base) => {
	let employer = 0;
	let employee = 0;
	for (let index = 0; index < 20; index += 1) {
		const tax = ladder(Math.max(0, base + employer), ctx.lookup.brackets);
		employee = items > 0 && income > 0 ? (tax * Math.min(items, income)) / (income + employer) : 0;
		employer = tax - employee;
	}
	return { employer, employee };
};
// The month's taxable income through the monthly column; the annual column is the finalisation's.
return Math.max(0, split(assessable).employer - before('PIT', 'employer'));

UNION_DUES.eligibility:
const extension = get(ctx.subject.employment, 'employee_extension_data', {});
const review = get(extension, 'insurance_review', null);
return (
	get(extension, 'statutory.UNION_DUES.union_member', false) === true &&
	get(review, 'union_dues_exempt', false) !== true
);

UNION_DUES.employee_amount:
const employment = ctx.subject.employment;
const terms = employment.terms;
const extension = get(employment, 'employee_extension_data', {});
const review = get(extension, 'insurance_review', null);
const month = get(ctx.balances, 'month', {});
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const monthly = Number(get(ctx.subtotals, 'BASIC', 0)) + before('BASIC');
const fixed = Object.entries(get(terms, 'allowances', {})).reduce(
	(total, [code, allowance]) => !(ctx.allowance ?? []).some((row) => row.code === code && row.include_in_rate === true) ? total : total + Number(get(allowance, 'amount', 0)),
	0
);
const reviewed = get(review, 'month', '') === String(ctx.as_of).substring(0, 7) ? Number(get(review, 'salary_vnd', monthly + fixed)) : monthly + fixed;
const insurance = Math.min(Math.max(reviewed, ctx.lookup.insurance_floor), ctx.lookup.insurance_ceiling);
return Math.min(insurance * ctx.lookup.employee_rate, ctx.lookup.cap) - before('UNION_DUES.employee');

