TERMINATION_NOTICE.effects:
const term = get(ctx.entry, 'signed_contract_period', null);
const end = get(term, 'to', null);
// A contract's length includes its last day: 1 Jan to 31 Dec is the twelve months of Labour Code art.36(2)(b).
const months = end == null ? null : calendar_completed_months(term.from, add_days(end, 1));
const agreed = get(ctx.entry.terms, 'notice_period.value', null);
const special = get(ctx.entry.employee_extension_data, 'special_role_notice', false) === true;
const noticeDays = () => {
	if (agreed != null) return Number(agreed);
	if (get(ctx.entry.employee_extension_data, 'long_illness', false) === true) return ctx.lookup.short_term_days;
	if (special && months != null && months < 12) return Math.ceil(calendar_distance_days(term.from, add_days(end, 1)) / 4);
	if (special) return ctx.lookup.special_role_days;
	if (months == null) return ctx.lookup.indefinite_days;
	if (months >= 12) return ctx.lookup.term_30_days;
	return ctx.lookup.short_term_days;
};
const notice = noticeDays();
const key = 'TERMINATION_NOTICE:' + ctx.entry.id + ':exit:' + ctx.entry.effective_range.to;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [
	{
		entity_id: ctx.entry.entity_id,
		employee_id: ctx.entry.employee_id,
		employment_id: ctx.entry.id,
		title: ctx.lookup.title,
		due_on: notice === ctx.lookup.short_term_days
			? add_working_days(ctx.entry.effective_range.to, -notice, get(ctx, 'reads.holiday', []).map((h) => h.date), [0])
			: add_days(ctx.entry.effective_range.to, -notice),
		occurrence_key: key
	}
];

