MINIMUM_WAGE_FLOOR.validate:
const on = String(ctx.entry.effective_range.from);
const employer = (ctx.reads.entity_profile_version ?? []).find(
	(v) =>
		v.status === 'SEALED' &&
		v.effective_range != null &&
		String(v.effective_range.from) <= on &&
		(v.effective_range.to == null || String(v.effective_range.to) >= on),
);
if (employer == null) return false;
const region = get(employer, 'entity_extension_data.region', null);
const floor = get(ctx.lookup.minimum_wage.by_region, region, null);
return floor === null || ctx.entry.terms.rate.amount >= floor;

OVERTIME_MONTHLY_CAP.validate:
const from = month_start(ctx.entry.work_date);
const to = month_end(ctx.entry.work_date);
const siblings = ctx.reads.roster_entry.filter((day) => day.work_date >= from && day.work_date <= to && day.work_date !== ctx.entry.work_date);
const minutes =
	sum(siblings.map((day) => interval_minutes(day.planned_overtime_intervals ?? []))) +
	interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
return minutes / 60 <= ctx.lookup.overtime_hours;

OVERTIME_DAILY_CAP.validate:
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []) / 60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []) / 60;
if (overtime === 0) return true;
const normal = worked - overtime;
return normal > 0 ? overtime <= ctx.lookup.share * normal : worked <= ctx.lookup.daily_hours;

DAMAGE_DEDUCTION_CEILING.validate:
const slip = ctx.reads.payslip.reduce(
	(last, row) => (last === null || String(row.period) > String(last.period) ? row : last),
	null
);
if (slip === null) return true;
const paid =
	get(slip, 'gross_earnings', 0) - get(slip, 'employee_statutory', 0) - get(slip, 'tax_withheld', 0);
return ctx.entry.quantity <= ctx.lookup.deduction_share * paid;

OVERTIME_ANNUAL_CAP.validate:
const year = ctx.entry.work_date.substring(0, 4);
const siblings = ctx.reads.roster_entry.filter(
	(day) => day.work_date.substring(0, 4) === year && day.work_date !== ctx.entry.work_date
);
const hours =
	(sum(siblings.map((day) => interval_minutes(day.planned_overtime_intervals ?? []))) +
		interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? [])) /
	60;
const on = String(ctx.entry.work_date);
const employer = (ctx.reads.entity_profile_version ?? []).find(
	(v) =>
		v.status === 'SEALED' &&
		v.effective_range != null &&
		String(v.effective_range.from) <= on &&
		(v.effective_range.to == null || String(v.effective_range.to) >= on),
);
if (employer == null) return false;
const cap =
	get(employer, 'entity_extension_data.overtime_300h_sector', false) === true
		? ctx.lookup.extended_hours
		: ctx.lookup.ordinary_hours;
return hours <= cap;

REGION_REQUIRED.validate:
const on = String(ctx.entry.effective_range.from);
const employer = (ctx.reads.entity_profile_version ?? []).find(
	(v) =>
		v.status === 'SEALED' &&
		v.effective_range != null &&
		String(v.effective_range.from) <= on &&
		(v.effective_range.to == null || String(v.effective_range.to) >= on),
);
if (employer == null) return false;
return ['I', 'II', 'III', 'IV'].includes(get(employer, 'entity_extension_data.region', null));

HOURLY_MINIMUM_WAGE.validate:
const on = String(ctx.entry.effective_range.from);
const employer = (ctx.reads.entity_profile_version ?? []).find(
	(v) =>
		v.status === 'SEALED' &&
		v.effective_range != null &&
		String(v.effective_range.from) <= on &&
		(v.effective_range.to == null || String(v.effective_range.to) >= on),
);
if (employer == null) return false;
const region = get(employer, 'entity_extension_data.region', null);
const floor = get(ctx.lookup.hourly_by_region, region, null);
if (floor === null) return true;
const rate = ctx.entry.terms.rate;
if (rate.unit === 'HOURLY') return rate.amount >= floor;
// A day converts to an hour over the normal hours of the day, or to a month over the normal days; either floor met is enough (art.4(3)).
const hours = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
if (!(hours > 0)) return false;
if (rate.amount / hours >= floor) return true;
const days = Number(get(ctx.entry, 'terms.normal_days_per_week', 0));
return (rate.amount * days * 52) / 12 >= get(ctx.lookup.minimum_wage.by_region, region, Infinity);

PROBATION_WAGE.condition:
const rate = get(ctx.entry, 'terms.rate', null);
if (get(ctx.entry, 'terms.probation_period', null) === null) return false;
if (rate === null) return false;
