PREGNANT_OR_INFANT_NIGHT_OVERTIME.validate:
// Labour Code art.137(1): pregnancy (a) has no consent exception; an infant under 12 months (b) needs the day's consent.
const contract = ctx.subject.employment;
const date = ctx.entry.work_date;
const consent = get(ctx.entry, 'consent', {});
const children = get(contract, 'family', []).filter((member) => member.relation === 'CHILD');
const pregnant = children.some((child) => {
	const due = get(child, 'expected_on', null);
	const born = get(child, 'born_on', null);
	return due !== null && born === null && date >= add_months(due, -ctx.lookup.advance_months);
});
const night = clock_window_minutes(
	get(ctx.entry, 'actual_worked_intervals', []) ?? [],
	"Asia/Ho_Chi_Minh",
	ctx.lookup.night_from,
	ctx.lookup.night_to
);
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
if (pregnant) return night === 0 && overtime === 0;
const infant = children.some((child) => {
	const born = get(child, 'born_on', null);
	return born !== null && add_months(born, ctx.lookup.infant_months) > date;
});
if (!infant) return true;
return (
	(night === 0 || get(consent, 'night_work', false) === true) &&
	(overtime === 0 || get(consent, 'overtime', false) === true)
);

MINOR_WORKING_TIME.validate:
