const week = ctx.reads.roster_entry.filter(
	(day) => day.work_date !== ctx.entry.work_date && day.work_date >= add_days(ctx.entry.work_date, -6)
);
const weekly =
	(sum(week.map((day) => interval_minutes(day.actual_worked_intervals ?? []))) +
		interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? [])) /
	60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
