lookup.entitlement:
// Labour Code 45/2019/QH14 art.113(1): 12 working days, 14 for a minor, a worker with a disability or arduous, toxic or
// dangerous work, 16 for especially arduous, toxic or dangerous work; art.114: one more day for every five full years.
const contract = ctx.subject.employment;
const facts = get(contract, 'employee_extension_data', {});
const category = get(contract, 'terms.statutory_work_category', null);
const extra = Math.max(0, ...ctx.lookup.extra_days.filter((row) => {
	const fact = get(row, 'fact', null);
	const kind = get(row, 'category', null);
	return (fact != null && get(facts, fact, false) === true) || (kind != null && kind === category);
}).map((row) => Number(get(row, 'days', 0))));
const service = calendar_completed_months(get(contract, 'service_started_on', contract.effective_range.from), ctx.as_of);
const [opening] = ctx.lookup.service_bands;
const days = ctx.lookup.service_bands.filter((band) => band.service_months <= Math.max(service, opening.service_months)).at(-1).days + extra;
const joined = get(contract, 'employment_started_on', contract.effective_range.from);
if (joined <= ctx.as_of.slice(0, 4) + '-01-01') return days;
// Labour Code art.113(2); Decree 145/2020/ND-CP art.66(1): in the joining year, those days, seniority included, / 12 x the
// months worked in the year, each counted once its last day is served.
// Decree 145/2020/ND-CP art.66(2): the joining month counts when its working days from the start reach 50% of its normal
// working days in the agreed week.
const off = [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - get(contract, 'terms.normal_days_per_week', 5));
const working = (from, to) => {
	let count = 0;
	for (let day = from; day <= to; day = add_days(day, 1)) if (!off.includes(weekday(day))) count += 1;
	return count;
};
const end = month_end(joined);
const countedFirst = end <= ctx.as_of && working(joined, end) >= 0.5 * working(month_start(joined), end) ? 1 : 0;
const months = countedFirst + Math.max(0, calendar_completed_months(add_days(end, 1), add_days(ctx.as_of, 1)));
return round((days * months) / 12, 0.01);

