PIT.employee_amount:
const employment = ctx.subject.employment;
const terms = employment.terms;
const pit = get(employment, 'employee_extension_data.statutory.PIT', {});
// A recovery takes back income the memo row cannot hold below zero.
const remuneration = Number(get(ctx.statutory, 'PIT_TAXABLE_INCOME.employer', 0)) + Math.min(0, Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0)));
const residency = get(terms, 'residency_status', null);
if (residency == null)
	throw 'Record the tax residence on the sealed contract (CITIZEN, PERMANENT_RESIDENT, RESIDENT or NON_RESIDENT); Vietnamese law presumes neither residence nor non-residence.';
const signed = get(employment, 'signed_contract_period', null);
const shortContract =
	get(signed, 'to', null) != null &&
	add_months(signed.from, ctx.lookup.short_term_months) > add_days(signed.to, 1);
const shortTerm =
	shortContract || ['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(get(employment, 'engagement', ''));
const committed = get(pit, 'commitment_form', false) === true;
const borne = get(terms, 'employer_bears_income_tax', false) === true;
// Decree 253/2026/NĐ-CP art.46(4)(c): only the tax the employer bears is income; the allowances the contract leaves to the employee bear their own share at the month's rate.
const items = !borne || get(ctx.run, 'kind', '') === 'OFF_CYCLE' ? 0 : sum(get(terms, 'employee_borne_tax_items', []).map((code) => Number(get(terms, 'allowances.' + code + '.amount', 0))));
if (borne && items === 0) return 0;
const taxed = borne ? Math.max(0, Math.min(items, remuneration)) : remuneration;
if (residency === 'NON_RESIDENT') return taxed * ctx.lookup.non_resident_rate;
if (shortTerm && committed) return 0;
if (shortTerm && remuneration < ctx.lookup.short_term_threshold) return 0;
if (shortTerm) return taxed * ctx.lookup.short_term_rate;
const insurance =
	Number(get(ctx.statutory, 'SI.employee', 0)) +
	Number(get(ctx.statutory, 'HI.employee', 0)) +
	Number(get(ctx.statutory, 'UI.employee', 0));
const pension = Number(get(ctx.statutory, 'PIT_PENSION_DEDUCTION.employer', 0));
const dependants = Number(get(pit, 'dependants', 0));
const month = get(ctx.balances, 'month', {});
const heldIn = (paid, code) => (Object.hasOwn(month, paid + '.' + code) ? Number(month[paid + '.' + code]) : 0);
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const before = (code, side) => heldIn(paidMonth, code + '.' + side);
const earlierInsurance = before('SI', 'employee') + before('HI', 'employee') + before('UI', 'employee');
const monthlyDeduction = ctx.lookup.personal_deduction + ctx.lookup.dependant_deduction * dependants;
const assessable = Math.max(
	0,
	before('PIT_TAXABLE_INCOME', 'employer') +
		remuneration -
		earlierInsurance -
		insurance -
		Math.min(before('PIT_PENSION_DEDUCTION', 'employer') + pension, ctx.lookup.pension_cap) -
		monthlyDeduction
);
const income = before('PIT_TAXABLE_INCOME', 'employer') + Number(get(ctx.statutory, 'PIT_TAXABLE_INCOME.employer', 0));
const split = (base) => {
	let employer = 0;
	let employee = 0;
	for (let index = 0; index < 20; index += 1) {
		const tax = ladder(Math.max(0, base + employer), ctx.lookup.brackets);
		employee = items > 0 && income > 0 ? (tax * Math.min(items, income)) / (income + employer) : 0;
		employer = tax - employee;
	}
	return { employer, employee };
};
if (borne) return split(assessable).employee - before('PIT', 'employee');
// The month's taxable income through the monthly column; the annual column is the finalisation's.
const monthly = ladder(assessable, ctx.lookup.brackets) - before('PIT', 'employee');
if (String(get(ctx.run, 'pay_date', ctx.as_of)).substring(5, 7) !== '12') return monthly;
if (get(pit, 'finalisation_authorised', false) !== true) return monthly;
// Decree 253/2026 arts.46, 48, 51: the year's income less twelve personal deductions, the dependants' months and the year's insurance and pension, on the annual column (the monthly bands × 12).
const paid = get(ctx.balances, 'statutory_contribution', {});
const held = (key) => (Object.hasOwn(paid, key) ? Number(paid[key]) : 0);
const months = 12;
const taxYear = String(get(ctx.run, 'pay_date', ctx.as_of)).substring(0, 4);
const monthsFrom = (from) => {
	if (from.substring(0, 4) > taxYear) return 0;
	if (from.substring(0, 4) < taxYear) return months;
	return months + 1 - Number(from.substring(5, 7));
};
const registered = get(pit, 'dependants_registered_from', []);
const dependantMonths =
	registered.length === 0 ? dependants * months : sum(registered.map(monthsFrom));
const annual = Math.max(
	0,
	held('PIT_TAXABLE_INCOME.employer') +
		remuneration -
		held('PIT_PENSION_DEDUCTION.employer') -
		pension -
		held('SI.employee') -
		held('HI.employee') -
		held('UI.employee') -
		insurance -
		months * ctx.lookup.personal_deduction -
		dependantMonths * ctx.lookup.dependant_deduction
);
const due = months * ladder(annual / months, ctx.lookup.brackets);
return due - held('PIT.employee');

