PIT_TAXABLE_INCOME.employer_amount:
// The month's taxable income, less what this month already counted: each subtotal holds one treatment, so every cap applies to what the month paid.
const month = get(ctx.balances, 'month', {});
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const extension = get(ctx.subject.employment, 'employee_extension_data', {});
const subtotal = (code) => Number(get(ctx.subtotals, code, 0));
const meal = subtotal('MEAL_PAY') - subtotal('PAID_BASIC');
const workExpense = subtotal('WORK_EXPENSE_PAY') - subtotal('MEAL_PAY');
// Housing the employer pays is no pay line: the contract amount, on the share of the salary BASIC pays, on-cycle.
const housingRate = Number(get(ctx.subject.employment, 'terms.rate.amount', 0));
const housingAmount = Number(get(ctx.subject.employment, 'terms.allowances.HOUSING.amount', 0));
const housing =
	get(ctx.run, 'kind', '') === 'OFF_CYCLE' || get(ctx.subject.employment, 'terms.rate.unit', '') !== 'MONTHLY'
		? 0
		: round(housingRate > 0 ? (housingAmount * subtotal('BASIC')) / housingRate : housingAmount);
const outside = subtotal('PIT_EXEMPT_PAY') - subtotal('PENSION_PAY');
// Statutory pay above what an employer's own rest-day multiple adds; that excess stays taxable.
const workDays = get(ctx, 'work.days', []);
const holidayDay = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const restDay = (d) => get(d, 'day_type', '') === 'REST' && !holidayDay(d);
const employerRest = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const aboveStatute =
	employerRest > ctx.lookup.rest_day_multiple
		? sum(workDays.filter(restDay).map((d) => Number(get(d, 'worked_hours', 0)) * Number(get(d, 'hour_rate', 0)))) *
			(employerRest - ctx.lookup.rest_day_multiple)
		: 0;
const statutoryOvertime = Math.max(0, Number(ctx.overtime) - aboveStatute);
// Decree 253/2026/NĐ-CP art.26(1): night and overtime pay within the Labour Code's hours is exempt whole; the roster rules refuse
// hours past those limits.
const exemptOvertime = statutoryOvertime;
const fixedMealCap = ctx.lookup.meal_allowance_cap;
const mealCap =
	fixedMealCap == null
		? get(extension, 'cash_meal_policy_limit_vnd', null)
		: fixedMealCap;
if (mealCap == null && meal > 0)
	throw 'Record the documented cash-meal policy limit for this pay month.';
const employerLimit = Number(
	get(ctx.subject.employer.entity_extension_data, 'work_expense_limit', 0)
);
const wages = Math.max(
	0,
	subtotal('ADDITIONAL_WAGES') - meal - workExpense - outside - exemptOvertime
);
const ratio = ctx.lookup.housing_exempt_ratio;
const counted = before('PIT_TAXABLE_INCOME.employer');
const earlierMeal = before('MEAL_PAY') - before('PAID_BASIC');
const earlierWorkExpense = before('WORK_EXPENSE_PAY') - before('MEAL_PAY');
const rate = Number(get(ctx.subject.employment, 'terms.rate.amount', 0));
const earlierHousing = rate > 0 ? (Number(get(ctx.subject.employment, 'terms.allowances.HOUSING.amount', 0)) * before('BASIC')) / rate : 0;
const capped = (paidMeal, paidExpense) =>
	Math.max(0, paidMeal - Number(mealCap ?? 0)) + Math.max(0, paidExpense - employerLimit);
const otherTaxable =
	Math.max(counted - earlierHousing, counted / (1 + ratio)) +
	wages +
	capped(earlierMeal + meal, earlierWorkExpense + workExpense) -
	capped(earlierMeal, earlierWorkExpense);
return Math.max(0, otherTaxable + Math.min(earlierHousing + housing, ratio * otherTaxable) - counted);

MINIMUM_WAGE_FLOOR.validate:
const on = String(ctx.entry.effective_range.from);
const employer = (ctx.reads.entity_profile_version ?? []).find(
	(v) =>
		v.status === 'SEALED' &&
		v.effective_range != null &&
		String(v.effective_range.from) <= on &&
		(v.effective_range.to == null || String(v.effective_range.to) >= on),
);
if (employer == null) return false;
const region = get(employer, 'entity_extension_data.region', null);
const floor = get(ctx.lookup.minimum_wage.by_region, region, null);
return floor === null || ctx.entry.terms.rate.amount >= floor;
